<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$configFile = APP_ROOT . '/config/config.php';
if (is_file($configFile) && ($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'GET') { http_response_code(409); exit('A instalação já foi configurada.'); }
$error = null; $done = false;
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
  try {
    $host=trim((string)($_POST['db_host']??'127.0.0.1')); $port=(int)($_POST['db_port']??3306); $name=trim((string)($_POST['db_name']??'')); $user=trim((string)($_POST['db_user']??'')); $pass=(string)($_POST['db_pass']??''); $adminName=trim((string)($_POST['admin_name']??'')); $adminEmail=strtolower(trim((string)($_POST['admin_email']??''))); $adminPass=(string)($_POST['admin_pass']??''); $brand=trim((string)($_POST['brand_name']??'')); if(!$name||!$user||!$adminName||!filter_var($adminEmail,FILTER_VALIDATE_EMAIL)||strlen($adminPass)<10)throw new RuntimeException('Preencha todos os campos; a senha do admin precisa ter pelo menos 10 caracteres.');
    $pdo=new PDO("mysql:host={$host};port={$port};dbname={$name};charset=utf8mb4",$user,$pass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]); $sql=file_get_contents(APP_ROOT.'/database/migrations/001_initial.sql'); foreach(array_filter(array_map('trim',preg_split('/;\s*(?:\r?\n|$)/',$sql))) as $statement)$pdo->exec($statement); $now=gmdate('Y-m-d H:i:s'); $pdo->prepare('INSERT INTO users(name,email,password_hash,role,status,created_at,updated_at)VALUES(?,?,?,?,?,?,?)')->execute([$adminName,$adminEmail,password_hash($adminPass,PASSWORD_DEFAULT),'office_admin','active',$now,$now]); foreach([['brand.name',$brand?:'Seu escritório','string'],['brand.primary','#FF6A1A','string'],['brand.navy','#0F172B','string'],['brand.logo','assets/brand/morais-logo.png','string'],['brand.favicon','assets/brand/favicon.jpg','string']] as $setting)$pdo->prepare('INSERT INTO settings(setting_key,setting_value,value_type,updated_at)VALUES(?,?,?,?,?)')->execute([$setting[0],$setting[1],$setting[2],$now]); $config=['app_key'=>bin2hex(random_bytes(32)),'db'=>['host'=>$host,'port'=>$port,'name'=>$name,'user'=>$user,'pass'=>$pass,'charset'=>'utf8mb4'],'app'=>['base_url'=>'','timezone'=>'America/Sao_Paulo','session_name'=>'onboarding_session','upload_dir'=>APP_ROOT.'/storage/uploads']]; if(!is_dir(dirname($configFile)))mkdir(dirname($configFile),0750,true); file_put_contents($configFile,"<?php\nreturn ".var_export($config,true).";\n",LOCK_EX); if(!is_dir(APP_ROOT.'/storage/uploads'))mkdir(APP_ROOT.'/storage/uploads',0750,true); $done=true;
  } catch(Throwable $e){$error='Não foi possível instalar: '.htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8');}
}
?><!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Instalação · Portal de onboarding</title><style>body{font:16px system-ui;background:#0f172b;color:#fff;max-width:720px;margin:40px auto;padding:20px}main{background:#18233a;padding:28px;border-radius:16px}label{display:block;margin:14px 0}input{display:block;width:100%;padding:12px;margin-top:6px;box-sizing:border-box}button{padding:13px 20px;background:#ff6a1a;color:#fff;border:0;border-radius:8px;font-weight:700}.error{color:#ffb4a0}.ok{color:#b4ffce}</style><main><h1>Instalação do portal</h1><?php if($done): ?><p class="ok">Instalação concluída. Remova ou bloqueie install.php e acesse o portal.</p><?php else: ?><p>Configure o banco e crie o primeiro administrador.</p><?php if($error): ?><p class="error"><?=$error?></p><?php endif; ?><form method="post"><label>Host do banco<input name="db_host" value="127.0.0.1" required></label><label>Porta<input name="db_port" value="3306" required></label><label>Nome do banco<input name="db_name" required></label><label>Usuário<input name="db_user" required></label><label>Senha<input name="db_pass" type="password"></label><hr><label>Nome do administrador<input name="admin_name" required></label><label>E-mail do administrador<input name="admin_email" type="email" required></label><label>Senha do administrador (mínimo 10 caracteres)<input name="admin_pass" type="password" minlength="10" required></label><label>Nome do escritório<input name="brand_name" placeholder="Morais Contabilidade" required></label><button>Instalar</button></form><?php endif; ?></main></html>
